"""FastAPI request dependencies and authentication helpers."""

from __future__ import annotations

import secrets
from typing import TYPE_CHECKING, Annotated

from fastapi import Header, Request

from app.models import ServiceError

if TYPE_CHECKING:
    from app.lifespan import Runtime


def get_runtime(request: Request) -> Runtime:
    runtime = getattr(request.app.state, "runtime", None)
    if runtime is None:
        raise ServiceError(
            "service_not_ready",
            "The parser service is still starting",
            status_code=503,
        )
    return runtime


def _bearer_token(authorization: str | None) -> str | None:
    if not authorization:
        return None
    scheme, separator, token = authorization.partition(" ")
    if separator and scheme.lower() == "bearer" and token:
        return token.strip()
    return None


def _matches(candidate: str | None, expected: str) -> bool:
    if candidate is None or not candidate:
        return False
    return secrets.compare_digest(candidate, expected)


async def require_api_key(
    request: Request,
    authorization: Annotated[str | None, Header()] = None,
    x_api_key: Annotated[str | None, Header(alias="X-API-Key")] = None,
) -> None:
    """Require the optional public API key without leaking comparison details."""

    expected = request.app.state.settings.api_key
    if expected is None:
        return
    if _matches(x_api_key, expected) or _matches(_bearer_token(authorization), expected):
        return
    raise ServiceError("invalid_api_key", "A valid API key is required", status_code=401)


async def require_admin_token(
    request: Request,
    authorization: Annotated[str | None, Header()] = None,
    x_admin_token: Annotated[str | None, Header(alias="X-Admin-Token")] = None,
) -> None:
    """Protect state-changing administrative endpoints with a separate token."""

    expected = request.app.state.settings.admin_token
    if _matches(x_admin_token, expected) or _matches(_bearer_token(authorization), expected):
        return
    raise ServiceError("invalid_admin_token", "A valid admin token is required", status_code=401)

api/jobs.py.utf8:
"""Persistent job status, event, result, retry, and deletion endpoints."""

from __future__ import annotations

from pathlib import Path
from typing import Annotated
from urllib.parse import quote

import orjson
from fastapi import APIRouter, Depends, Form, Header, Query, Request, Response
from fastapi.responses import FileResponse, StreamingResponse

from app.api.dependencies import get_runtime, require_api_key
from app.api.schemas import DeleteJobResponse, JobResponse, PublicContentAsset
from app.models import (
    JobEvent,
    JobRecord,
    JobStatus,
    ServiceError,
)

router = APIRouter(
    prefix="/v1/content/jobs",
    tags=["jobs"],
    dependencies=[Depends(require_api_key)],
)


async def _job_response(request: Request, record: JobRecord) -> JobResponse:
    return JobResponse.from_record(record)


@router.get("/{job_id}", response_model=JobResponse, summary="Get persistent job state")
async def get_content_job(job_id: str, request: Request) -> JobResponse:
    record = await get_runtime(request).job_service.get_job(job_id)
    return await _job_response(request, record)


def _sse(event: JobEvent) -> bytes:
    data = {"type": event.event, "job_id": event.job_id, **event.data}
    payload = orjson.dumps(data).decode("utf-8")
    return f"id: {event.id}\nevent: {event.event}\ndata: {payload}\n\n".encode()


@router.get("/{job_id}/events", summary="Stream job progress as Server-Sent Events")
async def content_job_events(
    job_id: str,
    request: Request,
    last_event_id: Annotated[str | None, Header(alias="Last-Event-ID")] = None,
) -> StreamingResponse:
    parsed_last_id: int | None = None
    if last_event_id:
        try:
            parsed_last_id = int(last_event_id)
        except ValueError as exc:
            raise ServiceError(
                "invalid_last_event_id",
                "Last-Event-ID must be an integer",
                status_code=400,
            ) from exc

    service = get_runtime(request).job_service
    await service.get_job(job_id)

    async def stream():
        async for event in service.events(job_id, last_event_id=parsed_last_id):
            if await request.is_disconnected():
                break
            yield _sse(event)

    return StreamingResponse(
        stream(),
        media_type="text/event-stream",
        headers={
            "Cache-Control": "no-cache, no-transform",
            "X-Accel-Buffering": "no",
        },
    )


def _download_headers(filename: str, suffix: str) -> dict[str, str]:
    stem = Path(filename).stem or "content"
    ascii_stem = "".join(
        character for character in stem if character.isascii() and character.isalnum()
    )
    fallback = f"{ascii_stem or 'content'}{suffix}"
    encoded = quote(f"{stem}{suffix}")
    return {"Content-Disposition": f"attachment; filename={fallback}; filename*=UTF-8''{encoded}"}


@router.get(
    "/{job_id}/result",
    response_class=Response,
    summary="Read the completed GFM Markdown result",
    responses={200: {"content": {"text/markdown": {}}}},
)
async def get_content_result(
    job_id: str,
    request: Request,
    download: Annotated[bool, Query()] = False,
) -> Response:
    service = get_runtime(request).job_service
    record = await service.get_job(job_id)
    result = await service.get_result(job_id)
    headers = {"X-Content-ID": job_id}
    if download:
        headers.update(_download_headers(record.filename, ".md"))
    return Response(
        content=result,
        media_type="text/markdown; charset=utf-8",
        headers=headers,
    )


@router.post("/{job_id}/retry", response_model=JobResponse, summary="Retry a failed job")
async def retry_content_job(
    job_id: str,
    request: Request,
    unit_range: Annotated[str | None, Form()] = None,
) -> JobResponse:
    record = await get_runtime(request).job_service.retry_job(job_id, unit_range=unit_range)
    return JobResponse.from_record(record)


@router.delete(
    "/{job_id}",
    response_model=DeleteJobResponse,
    summary="Cancel an active job or delete a terminal job",
)
async def delete_content_job(job_id: str, request: Request) -> DeleteJobResponse:
    service = get_runtime(request).job_service
    record = await service.get_job(job_id)
    if record.status in {JobStatus.QUEUED, JobStatus.RUNNING}:
        await service.cancel_job(job_id)
        return DeleteJobResponse(id=job_id, status="cancelled")
    await service.delete_job(job_id)
    return DeleteJobResponse(id=job_id, status="deleted")


@router.get(
    "/{job_id}/assets",
    response_model=list[PublicContentAsset],
    summary="List content assets",
)
async def get_content_assets(job_id: str, request: Request) -> list[PublicContentAsset]:
    assets = await get_runtime(request).job_service.get_assets(job_id)
    return [PublicContentAsset.from_asset(asset) for asset in assets]


def _parse_range(value: str, size: int) -> tuple[int, int]:
    if not value.startswith("bytes=") or "," in value:
        raise ServiceError("invalid_range", "only one byte range is supported", status_code=416)
    start_text, separator, end_text = value[6:].partition("-")
    if not separator:
        raise ServiceError("invalid_range", "invalid HTTP byte range", status_code=416)
    try:
        if start_text:
            start = int(start_text)
            end = int(end_text) if end_text else size - 1
        else:
            suffix = int(end_text)
            start = max(0, size - suffix)
            end = size - 1
    except ValueError as exc:
        raise ServiceError("invalid_range", "invalid HTTP byte range", status_code=416) from exc
    if start < 0 or end < start or start >= size:
        raise ServiceError(
            "range_not_satisfiable",
            "requested byte range is outside the asset",
            status_code=416,
            details={"size_bytes": size},
        )
    return start, min(end, size - 1)


@router.get("/{job_id}/assets/{asset_id}", summary="Download a content asset")
async def get_content_asset(job_id: str, asset_id: str, request: Request) -> Response:
    service = get_runtime(request).job_service
    assets = await service.get_assets(job_id)
    asset = next((item for item in assets if item.asset_id == asset_id), None)
    if asset is None:
        raise ServiceError("asset_not_found", "asset does not exist", status_code=404)
    try:
        path = service.storage.asset_path(job_id, asset_id)
    except ValueError as exc:
        raise ServiceError("invalid_asset_id", "invalid asset identifier", status_code=400) from exc
    if path is None:
        raise ServiceError("asset_missing", "persisted asset file is missing", status_code=500)
    range_header = request.headers.get("range")
    headers = {
        **_download_headers(asset.filename, ""),
        "Accept-Ranges": "bytes" if asset.kind.value == "video" else "none",
        "ETag": f'"{asset.sha256}"',
    }
    if asset.kind.value != "video" or range_header is None:
        return FileResponse(
            path, media_type=asset.mime_type, filename=asset.filename, headers=headers
        )
    start, end = _parse_range(range_header, asset.size_bytes)

    def stream():
        with path.open("rb") as handle:
            handle.seek(start)
            remaining = end - start + 1
            while remaining > 0:
                chunk = handle.read(min(1024 * 1024, remaining))
                if not chunk:
                    break
                remaining -= len(chunk)
                yield chunk

    headers.update(
        {
            "Content-Range": f"bytes {start}-{end}/{asset.size_bytes}",
            "Content-Length": str(end - start + 1),
        }
    )
    return StreamingResponse(stream(), status_code=206, media_type=asset.mime_type, headers=headers)


@router.get("/{job_id}/bundle", summary="Download the parsed-content asset bundle")
async def get_content_bundle(job_id: str, request: Request) -> FileResponse:
    service = get_runtime(request).job_service
    record = await service.get_job(job_id)
    if record.status not in {JobStatus.COMPLETED, JobStatus.PARTIAL}:
        raise ServiceError("result_not_ready", "job result is not available", status_code=409)
    await service.get_assets(job_id)
    path = await service.storage.build_bundle(job_id)
    return FileResponse(
        path,
        media_type="application/zip",
        filename=f"{Path(record.filename).stem or 'content'}-assets.zip",
    )

mcp/server.py.utf8:
"""MCP tools, resources, and prompt mounted through Streamable HTTP."""

from __future__ import annotations

import base64
import binascii
from collections.abc import Callable
from dataclasses import dataclass
from typing import TYPE_CHECKING, Any

from mcp.server import MCPServer
from mcp.server.transport_security import TransportSecuritySettings
from starlette.applications import Starlette

from app.api.schemas import JobResponse, PublicContentAsset
from app.models import (
    ContentParseOptions,
    JobRecord,
    ScanPolicy,
    ServiceError,
)

if TYPE_CHECKING:
    from app.config import Settings
    from app.lifespan import Runtime


@dataclass(slots=True)
class McpBundle:
    server: MCPServer[Any]
    app: Starlette


def _service_error(error: ServiceError) -> dict[str, object]:
    return {"error": error.to_response().error.model_dump(mode="json", exclude_none=True)}


def create_mcp(runtime: Callable[[], Runtime], settings: Settings) -> McpBundle:
    """Build the MCP server once so its session manager shares app lifespan."""

    server: MCPServer[Any] = MCPServer(
        settings.app_name,
        version=settings.version,
        instructions=(
            "Parse PDF, DOCX, PPTX, images, and standalone videos into GFM Markdown. "
            "Headings, lists, paragraphs, and tables preserve the parser's visible structure; "
            "assets remain authenticated HTTP resources. Entity, relation, event, and financial "
            "fact extraction remain downstream."
        ),
    )

    @server.tool()
    async def parse_content(
        source_url: str | None = None,
        file_base64: str | None = None,
        filename: str | None = None,
        scan_policy: str = "auto",
        unit_range: str | None = None,
        language: str = "zh,en",
        describe_images: bool = False,
        description_language: str = "zh-CN",
        timeout_seconds: int | None = None,
        prefer_async: bool = False,
    ) -> dict[str, object]:
        """Parse one HTTP(S) URL or one base64 document, image, or video."""

        if (source_url is None) == (file_base64 is None):
            return _service_error(
                ServiceError(
                    "invalid_source",
                    "Exactly one of source_url or file_base64 is required",
                )
            )
        if scan_policy not in {"auto", "skip"}:
            return _service_error(
                ServiceError(
                    "invalid_options",
                    "scan_policy must be auto or skip",
                    status_code=422,
                )
            )
        try:
            options = ContentParseOptions(
                scan_policy=ScanPolicy(scan_policy),
                unit_range=unit_range,
                language=[item.strip() for item in language.split(",") if item.strip()],
                describe_images=describe_images,
                description_language=description_language,  # type: ignore[arg-type]
                timeout_seconds=timeout_seconds,
            )
        except (ValueError, TypeError) as exc:
            return _service_error(ServiceError("invalid_options", str(exc), status_code=422))

        content: bytes | None = None
        if file_base64 is not None:
            if not filename:
                return _service_error(
                    ServiceError("filename_required", "filename is required with file_base64")
                )
            try:
                content = base64.b64decode(file_base64, validate=True)
            except (binascii.Error, ValueError):
                return _service_error(ServiceError("invalid_base64", "file_base64 is invalid"))
            if not content:
                return _service_error(ServiceError("empty_file", "The supplied file is empty"))

        job_service = runtime().job_service
        try:
            result = await job_service.parse_content(
                source_url=source_url,
                content=content,
                filename=filename,
                options=options,
                prefer_async=(
                    prefer_async
                    or bool(content is not None and len(content) > settings.mcp_max_inline_bytes)
                ),
            )
            if isinstance(result, JobRecord):
                return {
                    "delivery": "job",
                    **JobResponse.from_record(result).model_dump(mode="json", exclude_none=True),
                }
            if len(result.markdown) <= settings.mcp_max_result_chars:
                return {
                    "delivery": "inline",
                    "content_id": result.document_id,
                    "media_type": "text/markdown",
                    "content": result.markdown,
                }

            job = await job_service.get_job(result.document_id)
            return {
                "delivery": "job",
                "message": "Markdown exceeds the MCP inline limit; use the result URL.",
                **JobResponse.from_record(job).model_dump(mode="json", exclude_none=True),
            }
        except ServiceError as exc:
            return _service_error(exc)

    @server.tool()
    async def get_content_job(job_id: str) -> dict[str, object]:
        """Get the durable status of a content parsing job."""

        try:
            record = await runtime().job_service.get_job(job_id)
            return JobResponse.from_record(record).model_dump(mode="json", exclude_none=True)
        except ServiceError as exc:
            return _service_error(exc)

    @server.tool()
    async def get_content_result(job_id: str) -> dict[str, object]:
        """Get completed Markdown when small enough for MCP."""

        try:
            content = await runtime().job_service.get_result(job_id)
            if len(content) > settings.mcp_max_result_chars:
                return {
                    "job_id": job_id,
                    "delivery": "http",
                    "media_type": "text/markdown",
                    "result_url": f"/v1/content/jobs/{job_id}/result",
                    "message": "Markdown exceeds the MCP inline limit.",
                }
            return {
                "delivery": "inline",
                "job_id": job_id,
                "media_type": "text/markdown",
                "content": content,
            }
        except ServiceError as exc:
            return _service_error(exc)

    @server.tool()
    async def get_content_assets(job_id: str) -> dict[str, object]:
        """List asset metadata and authenticated HTTP download URLs without base64 data."""

        try:
            assets = await runtime().job_service.get_assets(job_id)
            return {
                "job_id": job_id,
                "assets": [
                    PublicContentAsset.from_asset(asset).model_dump(mode="json", exclude_none=True)
                    for asset in assets
                ],
                "bundle_url": f"/v1/content/jobs/{job_id}/bundle",
            }
        except ServiceError as exc:
            return _service_error(exc)

    @server.resource("moparse://health", mime_type="application/json")
    @server.resource("mosaicparse://health", mime_type="application/json")
    async def health_resource() -> dict[str, object]:
        """Return process and queue health without secrets."""

        service = runtime()
        return {
            "status": "ok",
            "version": service.settings.version,
            "uptime_seconds": service.uptime_seconds,
            "queue_depth": service.job_service.queue_depth,
            "queue_capacity": service.settings.max_queued_jobs,
        }

    @server.resource("moparse://backends", mime_type="application/json")
    @server.resource("mosaicparse://backends", mime_type="application/json")
    async def backends_resource() -> dict[str, object]:
        """Return actual Docling, GLM-OCR, and SDK probes."""

        items = await runtime().parser_service.probe_backends()
        return {"backends": [item.model_dump(mode="json", exclude_none=True) for item in items]}

    @server.resource("moparse://usage", mime_type="text/markdown")
    @server.resource("mosaicparse://usage", mime_type="text/markdown")
    def usage_resource() -> str:
        """Describe safe routing and the service boundary."""

        return (
            "# moparse usage\n\n"
            "- Scanned PDF pages are processed adaptively by default (`scan_policy=auto`).\n"
            "- Use `scan_policy=skip` only to retain scanned pages as assets without OCR or table extraction.\n"
            "- Inputs are HTTP(S) URLs or base64 data; local filesystem paths are rejected.\n"
            "- The only document result is GFM Markdown (`text/markdown`).\n"
            "- Tables remain Markdown tables; entity, relation, event, and financial extraction is downstream.\n"
            "- Large media assets are authenticated HTTP downloads, never inline base64.\n"
            "- Domain entity, relation, and event extraction remains downstream."
        )

    @server.prompt()
    def content_parse_workflow(content_kind: str = "ordinary PDF") -> str:
        """Parse content with automatic scanned-page routing."""

        return (
            f"Parse the {content_kind} with moparse using scan_policy=auto. Return GFM "
            "Markdown while preserving headings, lists, paragraphs, units, and logical tables. "
            "Use scan_policy=skip only when scanned PDF pages must remain unprocessed assets."
        )

    transport_security = TransportSecuritySettings(
        allowed_hosts=settings.mcp_allowed_host_list,
        allowed_origins=settings.mcp_allowed_origin_list,
    )
    app = server.streamable_http_app(
        streamable_http_path="/",
        json_response=True,
        stateless_http=True,
        max_request_body_size=settings.mcp_max_inline_bytes * 2,
        transport_security=transport_security,
        host=settings.host,
    )
    return McpBundle(server=server, app=app)

models/parse_options.py.utf8:
"""Stable public parsing options.

The rest of the application deliberately depends on these small models instead of
Docling's (frequently evolving) option objects.
"""

from __future__ import annotations

from enum import StrEnum
from typing import Annotated, Literal

from pydantic import BaseModel, ConfigDict, Field, field_validator, model_validator


class ParseProfile(StrEnum):
    # Adapter-only compatibility setting for persisted pre-0.4 jobs. New
    # HTTP/MCP requests never expose a quality profile.
    FAST = "fast"
    BALANCED = "balanced"
    ACCURATE = "accurate"


class ScanPolicy(StrEnum):
    """Public policy for scanned PDF pages."""

    AUTO = "auto"
    SKIP = "skip"


LanguageCode = Annotated[str, Field(min_length=1, max_length=32)]


class ContentParseOptions(BaseModel):
    """User-facing options shared by synchronous and asynchronous content parsing."""

    model_config = ConfigDict(extra="forbid", use_enum_values=False)

    # Retained only to decode old database records and tune internal adapters.
    # It is deliberately absent from public request/response contracts.
    profile: ParseProfile = Field(default=ParseProfile.BALANCED, exclude=True)
    scan_policy: ScanPolicy = ScanPolicy.AUTO
    unit_range: str | None = Field(default=None, max_length=2_048)
    language: list[LanguageCode] = Field(
        default_factory=lambda: ["zh", "en"], min_length=1, max_length=16
    )
    # Embedded PDF/Office images are always preserved as assets. Describing
    # every image can be expensive, so model-generated descriptions are opt-in.
    # Standalone image inputs are still analysed because the image is the source.
    describe_images: bool = False
    description_language: Literal["zh-CN", "en", "auto"] = "zh-CN"
    timeout_seconds: int | None = Field(default=None, ge=1, le=86_400)

    @model_validator(mode="before")
    @classmethod
    def migrate_legacy_profile(cls, value: object) -> object:
        """Map persisted profile-only options onto the scan-policy contract."""

        if not isinstance(value, dict) or "scan_policy" in value or "profile" not in value:
            return value
        normalized = dict(value)
        raw_profile = normalized.get("profile")
        if isinstance(raw_profile, ParseProfile):
            raw_profile = raw_profile.value
        normalized["scan_policy"] = (
            ScanPolicy.AUTO.value
            if raw_profile == ParseProfile.ACCURATE.value
            else ScanPolicy.SKIP.value
        )
        return normalized

    @field_validator("unit_range")
    @classmethod
    def normalize_page_range(cls, value: str | None) -> str | None:
        if value is None:
            return None
        value = value.strip()
        if not value:
            return None
        # Full range validation (including the document's upper bound) happens
        # after the source has been inspected.
        from app.utils.page_range import parse_page_range

        parse_page_range(value)
        return value

    @field_validator("language", mode="before")
    @classmethod
    def parse_languages(cls, value: object) -> object:
        if isinstance(value, str):
            value = [item.strip() for item in value.split(",") if item.strip()]
        return value

    @field_validator("language")
    @classmethod
    def unique_languages(cls, value: list[str]) -> list[str]:
        result: list[str] = []
        seen: set[str] = set()
        for language in value:
            normalized = language.strip().lower()
            if normalized and normalized not in seen:
                seen.add(normalized)
                result.append(normalized)
        if not result:
            raise ValueError("at least one OCR language is required")
        return result

    @property
    def page_range(self) -> str | None:
        """Internal adapter for the existing page-oriented document pipeline."""

        return self.unit_range

