"""Conservative, explainable output-quality diagnostics."""

from __future__ import annotations

import re
from collections import Counter
from dataclasses import dataclass, field

from app.models.parse_result import (
    DocumentParseResult,
    PageParseResult,
    PageSourceKind,
    PageStatus,
    PipelineWarning,
    QualitySummary,
    QualityVerdict,
    WarningSeverity,
)
from app.services.evidence_service import number_tokens
from app.utils.settings import setting


@dataclass(slots=True)
class QualityAssessment:
    acceptable: bool
    warnings: list[PipelineWarning] = field(default_factory=list)


class QualityService:
    # Some Chinese standards contain a broken ToUnicode map where Latin glyphs
    # decode as a run of CJK characters from the cattle/dog radical blocks,
    # e.g. "Remanufacturing" becomes "犚犲犿犪狀...". Requiring a long run keeps
    # ordinary Chinese words and short standard identifiers such as GB/T out.
    _MOJIBAKE_LATIN_RUN = re.compile(r"(?:[\u7280-\u72ff][ \t]*){6,}")
    _LOW_INFORMATION_REPEAT = re.compile(
        r"^(?:(?:来源|参考)链接|链接)(?:地址)?[：:]?$|^巨潮资讯网[（）()]*$",
        re.IGNORECASE,
    )

    def __init__(self, settings: object | None = None) -> None:
        self.min_page_characters = int(setting(settings, "quality_min_page_characters", 12))
        self.replacement_ratio = float(setting(settings, "quality_max_replacement_ratio", 0.02))
        self.repeat_threshold = int(setting(settings, "quality_repeat_threshold", 5))

    def inspect_page(self, page: PageParseResult) -> list[PipelineWarning]:
        content = (page.content or "").strip()
        warnings: list[PipelineWarning] = []
        if page.status == PageStatus.FAILED:
            return page.warnings
        if page.diagnostics and page.diagnostics.source_kind == PageSourceKind.SPARSE:
            warnings.append(
                PipelineWarning(
                    code="intentional_sparse_page",
                    message="page is visually sparse and its short output agrees with the native PDF evidence",
                    severity=WarningSeverity.INFO,
                    page_number=page.page_number,
                    backend=page.backend,
                    details={
                        "native_text_characters": page.diagnostics.native_text_characters,
                        "visual_ink_ratio": page.diagnostics.visual_ink_ratio,
                    },
                )
            )
        elif len(content) < self.min_page_characters:
            warnings.append(
                PipelineWarning(
                    code="low_text_content",
                    message=f"page contains fewer than {self.min_page_characters} non-whitespace characters",
                    page_number=page.page_number,
                    backend=page.backend,
                )
            )
        if content:
            replacements = content.count("\ufffd")
            if replacements / len(content) > self.replacement_ratio:
                warnings.append(
                    PipelineWarning(
                        code="high_replacement_character_ratio",
                        message="page contains an unusually high Unicode replacement-character ratio",
                        page_number=page.page_number,
                        backend=page.backend,
                    )
                )
            # Decimal points and repeated values are expected inside financial
            # tables. Table-specific checks below cover structural repetition;
            # the prose repetition detector must not split table numbers into
            # many identical sentence fragments.
            repeat_source = "\n".join(
                line
                for line in content.splitlines()
                if not line.lstrip().startswith("|") and not line.strip().startswith("<!--")
            )
            repeat_source = re.sub(r"https?://[^\s|）)]+", "", repeat_source, flags=re.IGNORECASE)
            fragments = [
                fragment
                for part in re.split(r"[\n。！？.!?]+", repeat_source)
                if 4 <= len(fragment := part.strip()) <= 120
                and not self._LOW_INFORMATION_REPEAT.fullmatch(re.sub(r"[ \t]+", "", fragment))
                and not re.search(r"(?:https?://|www\.)", fragment, re.IGNORECASE)
            ]
            repeated = [
                (fragment, count)
                for fragment, count in Counter(fragments).items()
                if count >= self.repeat_threshold
            ]
            if repeated:
                warnings.append(
                    PipelineWarning(
                        code="repeated_text",
                        message="page contains an abnormally repeated short fragment",
                        page_number=page.page_number,
                        backend=page.backend,
                        details={"repeat_count": max(count for _, count in repeated)},
                    )
                )
            rows = [
                line
                for line in content.splitlines()
                if line.strip().startswith("|") and line.count("|") >= 2
            ]
            outside_table = "\n".join(
                line for line in content.splitlines() if not line.strip().startswith("|")
            )
            table_numbers = Counter(number_tokens("\n".join(rows)))
            outside_numbers = Counter(
                number
                for line in outside_table.splitlines()
                if re.fullmatch(
                    r"[-−]?\(?\d[\d,]*(?:\.\d+)%?\)?",
                    line.strip(),
                )
                and any(marker in line for marker in (".", ",", "%", "−"))
                for number in number_tokens(line)
            )
            unanchored_count = sum((table_numbers & outside_numbers).values())
            if rows and unanchored_count:
                warnings.append(
                    PipelineWarning(
                        code="unanchored_table_numbers",
                        message="numbers emitted outside a table are duplicated inside table cells",
                        page_number=page.page_number,
                        backend=page.backend,
                        details={"duplicate_number_count": unanchored_count},
                    )
                )
            for row in rows:
                cells = [cell.strip() for cell in row.strip().strip("|").split("|")]
                populated = [
                    cell
                    for cell in cells
                    if cell
                    and not set(cell) <= {"-", ":", " "}
                    and cell not in {"不适用", "不適用", "N/A", "n/a"}
                    and not re.fullmatch(
                        r"[-−]?\(?\d[\d,]*(?:\.\d+)?%?\)?",
                        cell,
                    )
                ]
                if populated and max(Counter(populated).values()) >= self.repeat_threshold:
                    warnings.append(
                        PipelineWarning(
                            code="table_header_propagation",
                            message="a table row repeats the same non-empty cell across too many columns",
                            page_number=page.page_number,
                            backend=page.backend,
                        )
                    )
                    break
            if rows and max(row.count("|") - 1 for row in rows) > 24:
                warnings.append(
                    PipelineWarning(
                        code="table_shape_explosion",
                        message="a rendered table has an implausibly large number of columns",
                        page_number=page.page_number,
                        backend=page.backend,
                    )
                )
        diagnostics = page.diagnostics
        if diagnostics and diagnostics.detected_rotation_degrees in {90, 180, 270}:
            warnings.append(
                PipelineWarning(
                    code="rotated_scan",
                    message="page image content requires orientation normalization before reliable OCR",
                    severity=WarningSeverity.INFO,
                    page_number=page.page_number,
                    backend=page.backend,
                    details={"rotation_degrees": diagnostics.detected_rotation_degrees},
                )
            )
        if (
            diagnostics
            and diagnostics.source_kind == PageSourceKind.NATIVE
            and diagnostics.selected_strategy.value in {"docling", "mineru"}
            and diagnostics.native_text_characters
            and len(re.sub(r"\s+", "", content)) < diagnostics.native_text_characters * 0.20
        ):
            warnings.append(
                PipelineWarning(
                    code="visual_text_mismatch",
                    message="parsed output contains far less text than the measured native PDF layer",
                    page_number=page.page_number,
                    backend=page.backend,
                )
            )
        return warnings

    @classmethod
    def has_suspicious_unicode_mojibake(cls, content: str | None) -> bool:
        return bool(content and cls._MOJIBAKE_LATIN_RUN.search(content))

    @classmethod
    def suspicious_unicode_pages(cls, result: DocumentParseResult) -> list[int]:
        return [
            page.page_number
            for page in result.pages
            if page.status != PageStatus.FAILED
            and cls.has_suspicious_unicode_mojibake(page.content)
        ]

    def assess(self, result: DocumentParseResult) -> QualityAssessment:
        warnings: list[PipelineWarning] = []
        for page in result.pages:
            if page.status != PageStatus.FAILED and not (page.content or "").strip():
                if not any(warning.code == "no_usable_content" for warning in page.warnings):
                    page.warnings.append(
                        PipelineWarning(
                            code="no_usable_content",
                            message="page has no usable parsed content",
                            severity=WarningSeverity.ERROR,
                            page_number=page.page_number,
                            backend=page.backend,
                        )
                    )
                page.status = PageStatus.FAILED
            detected = self.inspect_page(page)
            existing_codes = {warning.code for warning in page.warnings}
            page.warnings.extend(
                warning for warning in detected if warning.code not in existing_codes
            )
            actionable = [
                warning for warning in page.warnings if warning.severity != WarningSeverity.INFO
            ]
            if actionable and page.status == PageStatus.COMPLETED:
                page.status = PageStatus.WARNING
            warnings.extend(page.warnings)
            if page.diagnostics is not None:
                visual = page.diagnostics.glm
                warning_codes = {warning.code for warning in page.warnings}
                if visual is not None:
                    if page.status == PageStatus.FAILED or warning_codes & {
                        "glm_sdk_timeout",
                        "glm_sdk_skipped_after_timeout",
                        "table_structure_invalid",
                    }:
                        page.diagnostics.quality_verdict = QualityVerdict.UNTRUSTED
                    elif visual.structure_issue_count > 0 or page.status == PageStatus.WARNING:
                        page.diagnostics.quality_verdict = QualityVerdict.DEGRADED
                    else:
                        page.diagnostics.quality_verdict = QualityVerdict.TRUSTED
                elif page.status in {PageStatus.WARNING, PageStatus.FAILED} or any(
                    warning.code
                    in {
                        "low_text_content",
                        "high_replacement_character_ratio",
                        "repeated_text",
                        "suspicious_unicode_mojibake",
                        "suspicious_unicode_glyphs",
                        "native_identifier_missing",
                        "native_heading_order_mismatch",
                        "reading_order_inversion",
                        "table_shape_explosion",
                        "table_header_propagation",
                        "unanchored_table_numbers",
                        "visual_text_mismatch",
                    }
                    for warning in page.warnings
                ):
                    page.diagnostics.quality_verdict = QualityVerdict.UNTRUSTED
                else:
                    page.diagnostics.quality_verdict = QualityVerdict.TRUSTED
        failed = sum(page.status == PageStatus.FAILED for page in result.pages)
        result.route_summary.failed_pages = failed
        existing_document_warnings = {
            (warning.code, warning.page_number) for warning in result.warnings
        }
        result.warnings.extend(
            warning
            for warning in warnings
            if (warning.code, warning.page_number) not in existing_document_warnings
        )
        acceptable = failed == 0 and not any(
            warning.severity == WarningSeverity.ERROR
            or warning.code
            in {
                "low_text_content",
                "high_replacement_character_ratio",
                "repeated_text",
                "suspicious_unicode_mojibake",
                "suspicious_unicode_glyphs",
                "native_identifier_missing",
                "native_heading_order_mismatch",
                "reading_order_inversion",
                "table_shape_explosion",
                "table_header_propagation",
                "unanchored_table_numbers",
                "visual_text_mismatch",
                "glm_sdk_timeout",
                "glm_sdk_skipped_after_timeout",
                "unresolved_visual_conflict",
            }
            for warning in warnings
        )
        self.summarize(result)
        return QualityAssessment(acceptable=acceptable, warnings=warnings)

    @staticmethod
    def summarize(result: DocumentParseResult) -> QualitySummary:
        summary = QualitySummary()
        for page in result.pages:
            diagnostics = page.diagnostics
            verdict = (
                diagnostics.quality_verdict
                if diagnostics
                else (
                    QualityVerdict.UNTRUSTED
                    if page.status in {PageStatus.WARNING, PageStatus.FAILED}
                    else QualityVerdict.TRUSTED
                )
            )
            if verdict == QualityVerdict.TRUSTED:
                summary.trusted_pages += 1
            elif verdict == QualityVerdict.DEGRADED:
                summary.degraded_pages += 1
            else:
                summary.untrusted_pages += 1
            if diagnostics and diagnostics.selected_strategy.value not in {"docling", "mineru"}:
                summary.repaired_pages += 1
            if diagnostics:
                visual = diagnostics.glm
                if visual is not None:
                    summary.visual_pages += 1
                    if summary.sdk_requests is None or visual.sdk_requests is None:
                        summary.sdk_requests = None
                    else:
                        summary.sdk_requests += visual.sdk_requests
                    if visual.glm_calls is not None:
                        summary.glm_calls = (summary.glm_calls or 0) + visual.glm_calls
                    summary.unresolved_visual_conflicts += visual.structure_issue_count
        result.quality_summary = summary
        return summary

    evaluate = assess

services/source_service.py.utf8:
"""Upload and URL materialization with size and SSRF enforcement."""

from __future__ import annotations

import asyncio
from collections.abc import AsyncIterator
from contextlib import asynccontextmanager
from email.message import Message
from pathlib import PurePosixPath
from urllib.parse import unquote, urlsplit, urlunsplit

import httpx

from app.models.error import ServiceError
from app.models.source import StoredSource
from app.security.file_validation import FileValidationError
from app.security.source_url import (
    SourceUrlError,
    ValidatedSourceUrl,
    validate_redirect_url,
    validate_source_url,
)
from app.services.storage_service import StorageService
from app.utils.settings import setting


class SourceService:
    def __init__(
        self,
        settings: object | None,
        storage: StorageService,
        http_client: httpx.AsyncClient | None = None,
    ) -> None:
        self.settings = settings
        self.storage = storage
        self.allow_source_urls = bool(setting(settings, "allow_source_urls", True))
        self.allow_private_source_urls = bool(setting(settings, "allow_private_source_urls", False))
        self.max_redirects = int(setting(settings, "source_url_max_redirects", 3))
        self.timeout_seconds = float(setting(settings, "source_url_timeout_seconds", 30))
        self.user_agent = str(setting(settings, "source_url_user_agent", "moparse/0.5.0"))
        self.max_upload_bytes = int(setting(settings, "max_upload_bytes", 200 * 1024 * 1024))
        self._owns_client = http_client is None
        self._client = http_client or httpx.AsyncClient(
            follow_redirects=False,
            timeout=httpx.Timeout(self.timeout_seconds),
            # Requests are pinned to validated IP literals. Avoid pooling a TLS
            # connection across two hostnames that happen to resolve to the same
            # address, because SNI is intentionally kept as the original host.
            limits=httpx.Limits(max_connections=16, max_keepalive_connections=0),
            trust_env=False,
        )

    @staticmethod
    def _pinned_url(validated: ValidatedSourceUrl, address: str) -> str:
        parsed = urlsplit(validated.url)
        literal = f"[{address}]" if ":" in address else address
        if parsed.port is not None:
            literal = f"{literal}:{parsed.port}"
        return urlunsplit((parsed.scheme, literal, parsed.path, parsed.query, ""))

    async def _send_validated(self, validated: ValidatedSourceUrl) -> httpx.Response:
        """Connect only to an address returned by the completed SSRF check."""

        original_authority = urlsplit(validated.url).netloc
        last_error: httpx.HTTPError | None = None
        for address in validated.addresses:
            request = self._client.build_request(
                "GET",
                self._pinned_url(validated, address),
                headers={
                    "User-Agent": self.user_agent,
                    "Accept": "application/pdf,image/*",
                    "Host": original_authority,
                    "Connection": "close",
                },
                # httpcore uses this for TLS SNI and certificate verification,
                # while the TCP connection target remains the validated IP.
                extensions={"sni_hostname": validated.hostname},
            )
            try:
                return await self._client.send(request, stream=True)
            except (httpx.ConnectError, httpx.ConnectTimeout) as exc:
                last_error = exc
        if last_error is not None:
            raise last_error
        raise httpx.ConnectError("source URL resolved to no usable addresses")

    @asynccontextmanager
    async def _stream_validated(
        self,
        validated: ValidatedSourceUrl,
    ) -> AsyncIterator[httpx.Response]:
        response = await self._send_validated(validated)
        try:
            yield response
        finally:
            await response.aclose()

    @staticmethod
    def _map_validation_error(exc: FileValidationError) -> ServiceError:
        status = 413 if exc.code in {"file_too_large", "too_many_pages"} else 415
        if exc.code in {"empty_file", "empty_document", "invalid_pdf", "invalid_image"}:
            status = 400
        return ServiceError(exc.code, str(exc), status_code=status)

    async def from_upload(self, job_id: str, upload: object) -> StoredSource:
        filename = getattr(upload, "filename", None) or "document"
        try:
            return await self.storage.save_stream(job_id, filename, upload)
        except FileValidationError as exc:
            raise self._map_validation_error(exc) from exc

    async def from_bytes(self, job_id: str, filename: str, content: bytes) -> StoredSource:
        try:
            return await self.storage.save_bytes(job_id, filename, content)
        except FileValidationError as exc:
            raise self._map_validation_error(exc) from exc

    @staticmethod
    def _response_filename(response: httpx.Response, url: str) -> str:
        disposition = response.headers.get("content-disposition")
        if disposition:
            message = Message()
            message["content-disposition"] = disposition
            candidate = message.get_filename()
            if candidate:
                return candidate
        path_name = PurePosixPath(unquote(urlsplit(url).path)).name
        return path_name or "document"

    async def from_url(self, job_id: str, source_url: str) -> StoredSource:
        try:
            # httpx timeouts are per network phase/read operation. This outer
            # deadline also stops a slow-drip peer from occupying a download
            # slot indefinitely by sending one chunk before every read timeout.
            async with asyncio.timeout(self.timeout_seconds):
                return await self._from_url(job_id, source_url)
        except TimeoutError as exc:
            raise ServiceError(
                "source_download_timeout",
                "source URL download timed out",
                status_code=504,
            ) from exc

    async def _from_url(self, job_id: str, source_url: str) -> StoredSource:
        if not self.allow_source_urls:
            raise ServiceError("source_urls_disabled", "URL sources are disabled", status_code=400)
        try:
            validated = await validate_source_url(
                source_url, allow_private=self.allow_private_source_urls
            )
            for redirect_count in range(self.max_redirects + 1):
                async with self._stream_validated(validated) as response:
                    if response.status_code in {301, 302, 303, 307, 308}:
                        if redirect_count >= self.max_redirects:
                            raise ServiceError(
                                "too_many_redirects",
                                "source URL exceeded redirect limit",
                                status_code=400,
                            )
                        validated = await validate_redirect_url(
                            validated.url,
                            response.headers.get("location", ""),
                            allow_private=self.allow_private_source_urls,
                        )
                        continue
                    if response.status_code < 200 or response.status_code >= 300:
                        raise ServiceError(
                            "source_download_failed",
                            f"source server returned HTTP {response.status_code}",
                            status_code=502,
                        )
                    content_length = response.headers.get("content-length")
                    if content_length:
                        try:
                            if int(content_length) > self.max_upload_bytes:
                                raise ServiceError(
                                    "file_too_large",
                                    "remote file exceeds the upload size limit",
                                    status_code=413,
                                )
                        except ValueError:
                            pass
                    filename = self._response_filename(response, validated.url)
                    try:
                        return await self.storage.save_chunks(
                            job_id,
                            filename,
                            response.aiter_bytes(1024 * 1024),
                            source_url=validated.url,
                        )
                    except FileValidationError as exc:
                        raise self._map_validation_error(exc) from exc
            raise ServiceError(
                "too_many_redirects", "source URL exceeded redirect limit", status_code=400
            )
        except SourceUrlError as exc:
            raise ServiceError(exc.code, str(exc), status_code=400) from exc
        except httpx.TimeoutException as exc:
            raise ServiceError(
                "source_download_timeout", "source URL download timed out", status_code=504
            ) from exc
        except httpx.HTTPError as exc:
            raise ServiceError(
                "source_download_failed", "source URL could not be downloaded", status_code=502
            ) from exc

    async def prepare(
        self,
        job_id: str,
        *,
        file: object | None = None,
        source_url: str | None = None,
        filename: str | None = None,
        content: bytes | None = None,
    ) -> StoredSource:
        choices = int(file is not None) + int(source_url is not None) + int(content is not None)
        if choices != 1:
            raise ServiceError(
                "source_conflict",
                "exactly one of file, source_url, or content must be provided",
                status_code=400,
            )
        if file is not None:
            return await self.from_upload(job_id, file)
        if source_url is not None:
            return await self.from_url(job_id, source_url)
        return await self.from_bytes(job_id, filename or "document", content or b"")

    async def close(self) -> None:
        if self._owns_client:
            await self._client.aclose()

